<?php require_once __DIR__.'/../app/bootstrap.php';require_login();if(user()['status']!=='active')exit('Cuenta no habilitada');verify_csrf();$body=trim($_POST['body']??'');if($body==='')redirect('index.php');$img=upload_image('image','posts');$q=db()->prepare('INSERT INTO posts(user_id,title,body,image) VALUES(?,?,?,?)');$q->execute([user()['id'],trim($_POST['title']??'')?:null,$body,$img]);flash('success','Publicación creada.');redirect('index.php');
